#!/usr/bin/env python3
"""Emit Source/PDF/lep_densities/<set>/bstrahl_pars.inc from the CIRCE
parameters of vendor/eepdfgrid/calcpdf_<collider>.f.

The dressed-lepton grids in eepdf.f are the Mellin convolution of a CIRCE
beamstrahlung spectrum with the ISR structure function.  The shared
Template/Common/Source/PDF/bstrahl.f exposes that convolution's integrand so
the x = xbs * xisr split can be sampled at event-writing time; the include
written here is the only part that depends on the density.  The same
include, with no beamstrahlung, is written as the default next to bstrahl.f.
"""
import os
import sys

# The exponential factor of the CIRCE spectrum is collider dependent:
# vendor/eepdfgrid/calcpdf_<collider>.f writes it as
#   'sqrt' : dexp(q*dsqrt(u))         (cepc240, fccee240, fccee365, ilc250)
#   'u15'  : dexp(q*u**1.5d0)         (ilc500)
#   'ym15' : dexp(q*(x/z)**(-1.5d0))  (clic3000) -- note: in x/z, not in u
# with u = 1-x/z.  bstrahl.f selects the form through bs_qform, numbered as
# below.  Getting this wrong is silent: the normalisation of the split
# drifts but nothing crashes, so test_bstrahl.f checks every set against
# Iapq() of the corresponding vendor file.
QFORM = {'sqrt': 1, 'u15': 2, 'ym15': 3}

# <density set> : (collider source, q-term form, a11, a01, a10, a00,
#                  p1, q1, p2, q2, p3, q3, p4, q4)
SETS = {
    'cepc240ll':  ('cepc240',  'sqrt', 0.8351,  0.3513,  0.3515,  0.1663,
                   -910.9, -17.28, -914.2, -17.27, -917.9, -15.44, -918.8, -15.45),
    'clic3000ll': ('clic3000', 'ym15', 0.7434,  0.04563, 0.04568, 0.003537,
                   -0.6016, -7.179e-3, -0.6089, -7.135e-3,
                   -0.5629, -7.464e-3, -0.5743, -7.259e-3),
    'fcce240ll':  ('fccee240', 'sqrt', 0.8698,  0.2863,  0.2853,  0.1092,
                   -901.2, -19.30, -916.5, -18.70, -899.2, -18.03, -918.7, -17.48),
    'fcce365ll':  ('fccee365', 'sqrt', 0.7883,  0.4056,  0.4059,  0.2281,
                   -714.3, -14.64, -714.5, -14.69, -714.7, -12.77, -717.1, -12.80),
    'ilc500ll':   ('ilc500',   'u15',  0.5012,  0.1613,  0.1613,  0.06379,
                   -8.514, -5.808, -8.505, -5.823, -7.535, -6.790, -7.481, -6.849),
}

# Sets with no beamstrahlung at all: pure ISR densities.
STUB_SETS = ['isronlyll', 'isrbetll', 'isrbetmll']


def d(x):
    """Fortran double literal."""
    s = repr(float(x))
    if 'e' in s:
        return s.replace('e', 'd')
    return s + 'd0'


KEYS = ['a11', 'a01', 'a10', 'a00',
        'p1', 'q1', 'p2', 'q2', 'p3', 'q3', 'p4', 'q4']

INC = """c     ------------------------------------------------------------------
c     Beamstrahlung parameters %(what)s.
c     Included by Source/PDF/bstrahl.f, which documents them.
c
%(comment)sc     Generated by vendor/eepdfgrid/gen_bstrahl.py -- do not edit by
c     hand.
c     ------------------------------------------------------------------
      logical bs_has
      integer bs_qform
      double precision bs_a11, bs_a01, bs_a10, bs_a00
      double precision bs_p1, bs_q1, bs_p2, bs_q2
      double precision bs_p3, bs_q3, bs_p4, bs_q4
      parameter (bs_has=%(has)s, bs_qform=%(qform)d)
      parameter (bs_a11=%(a11)s, bs_a01=%(a01)s)
      parameter (bs_a10=%(a10)s, bs_a00=%(a00)s)
      parameter (bs_p1=%(p1)s, bs_q1=%(q1)s)
      parameter (bs_p2=%(p2)s, bs_q2=%(q2)s)
      parameter (bs_p3=%(p3)s, bs_q3=%(q3)s)
      parameter (bs_p4=%(p4)s, bs_q4=%(q4)s)
"""


def inc_text(what, comment, has, qform, values):
    subs = dict(what=what, comment=comment,
                has='.true.' if has else '.false.', qform=qform)
    for key, val in zip(KEYS, values):
        subs[key] = d(val)
    return INC % subs


def write(path, text):
    with open(path, 'w') as fsock:
        fsock.write(text)
    print('wrote', path)


def main(root):
    pdf = os.path.join(root, 'Template', 'Common', 'Source', 'PDF')
    base = os.path.join(pdf, 'lep_densities')
    for name, pars in SETS.items():
        collider, qform = pars[0], pars[1]
        comment = ("c     CIRCE fit of vendor/eepdfgrid/calcpdf_%s.f.\n"
                   "c\n" % collider)
        write(os.path.join(base, name, 'bstrahl_pars.inc'),
              inc_text("of the '%s' lepton density" % name, comment,
                       True, QFORM[qform], pars[2:]))

    # No beamstrahlung: the whole density is the no-beamstrahlung x
    # no-beamstrahlung component, a11 = 1.  (All zeros would not even
    # compile: gfortran folds a01/dsqrt(a11) to 0/0 at compile time.)
    zeros = [1.] + [0.] * (len(KEYS) - 1)
    for name in STUB_SETS:
        comment = ("c     This density is pure ISR: there is no beamstrahlung "
                   "to split off,\nc     so the whole of x is ISR off a beam "
                   "lepton at its nominal energy.\nc\n")
        write(os.path.join(base, name, 'bstrahl_pars.inc'),
              inc_text("of the '%s' lepton density" % name, comment,
                       False, 0, zeros))

    comment = ("c     Default: no dressed-lepton density, so no beamstrahlung"
               ".  Replaced\nc     by lep_densities/<set>/bstrahl_pars.inc "
               "in copy_lep_densities().\nc\n")
    write(os.path.join(pdf, 'bstrahl_pars.inc'),
          inc_text('when no lepton density is selected', comment,
                   False, 0, zeros))


if __name__ == '__main__':
    main(sys.argv[1])
